sys_script_include.script:
function GetStore(vStore)
{
	var IsValidRecord = x_snc_devtools.IsValidRecord;
	var Clone = x_snc_devtools.Clone;
	var GetCountryRecord = x_snc_devtools.GetCountryRecord;

	var grStore = GetStoreRecord(vStore);
	if (IsValidRecord(grStore) == false)
	{
		return false;
	}
	var store = Clone(grStore);

	delete store.sys_created_on;
	delete store.sys_created_by;
	delete store.sys_meta;
	delete store.sys_mod_count;
	delete store.sys_updated_on;
	delete store.sys_updated_by;
	delete store.sys_tags;

	if (store.country != '')
	{
		var grCountry = GetCountryRecord(store.country);
		if (IsValidRecord(grCountry) == true)
		{
			store.country_name = grCountry.getDisplayValue();
		}

		if (store.subdivision != '')
		{
			var grSubdivision = x_snc_geodata.GetCountrySubdivisionRecord(store.subdivision);
			if (IsValidRecord(grSubdivision) == true)
			{
				store.subdivision_name = grSubdivision.getDisplayValue();
			}
		}
	}

	return store;
}
